<?php
require_once '../includes/farmacia.php';exigirPermiso('compras.ver');$db=farmaciaDb();$q=trim((string)($_GET['q']??''));$pagina=max(1,(int)($_GET['pagina']??1));$where=' WHERE c.NumeroDocumento LIKE ? OR p.Nombre LIKE ?';$params=['%'.$q.'%','%'.$q.'%'];
$stmt=$db->prepare('SELECT COUNT(*) FROM Compras c JOIN Proveedores p ON p.ProveedorID=c.ProveedorID'.$where);$stmt->execute($params);$total=(int)$stmt->fetchColumn();$paginas=max(1,(int)ceil($total/20));$pagina=min($pagina,$paginas);
$stmt=$db->prepare('SELECT c.CompraID,c.NumeroDocumento,c.FechaCompra,c.Total,c.Estado,p.Nombre FROM Compras c JOIN Proveedores p ON p.ProveedorID=c.ProveedorID'.$where.' ORDER BY c.CompraID DESC LIMIT 20 OFFSET '.(($pagina-1)*20));$stmt->execute($params);$filas=$stmt->fetchAll(PDO::FETCH_ASSOC);$verCostos=tienePermiso('medicamentos.costos');$titulo='Compras recibidas';require '../includes/header.php';
?>
<h1 class="page-title"><i class="bi bi-bag-plus"></i> Compras recibidas</h1><div class="card"><div class="card-header d-flex justify-content-between"><span>Recepciones de inventario</span><?php if(tienePermiso('compras.crear')): ?><a class="btn btn-light btn-sm" href="nueva.php">Registrar compra</a><?php endif; ?></div><div class="card-body"><form method="get" class="input-group mb-3"><input class="form-control" name="q" value="<?=h($q)?>" placeholder="Documento o proveedor" aria-label="Buscar compra"><button class="btn btn-primary">Buscar</button></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Compra</th><th>Fecha</th><th>Proveedor</th><th>Documento</th><th>Estado</th><?php if($verCostos): ?><th>Total</th><?php endif; ?><th>Acciones</th></tr></thead><tbody><?php foreach($filas as $c): ?><tr><td>#<?=$c['CompraID']?></td><td><?=h($c['FechaCompra'])?></td><td><?=h($c['Nombre'])?></td><td><?=h($c['NumeroDocumento'])?></td><td><span class="badge <?=$c['Estado']==='Anulada'?'bg-danger':'bg-success'?>"><?=h($c['Estado'])?></span></td><?php if($verCostos): ?><td><?=dinero($c['Total'])?></td><?php endif; ?><td><a class="btn btn-info btn-sm" href="ver.php?id=<?=$c['CompraID']?>">Ver recepción</a></td></tr><?php endforeach; ?><?php if(!$filas): ?><tr><td colspan="7" class="text-center text-muted">Todavía no hay compras recibidas.</td></tr><?php endif; ?></tbody></table></div><div class="d-flex justify-content-between"><span><?=$total?> compras · Página <?=$pagina?> de <?=$paginas?></span><div><?php foreach(['Anterior'=>$pagina-1,'Siguiente'=>$pagina+1] as $label=>$p): if($p>=1&&$p<=$paginas): ?><a class="btn btn-outline-primary btn-sm" href="?<?=h(http_build_query(['q'=>$q,'pagina'=>$p]))?>"><?=$label?></a> <?php endif; endforeach; ?></div></div></div></div>
<?php require '../includes/footer.php'; ?>
